// #824dde מסך הזמנת משתמש חדש (S-03, /users/invite): неверный формат email, пустые обязательные поля,
// email участника компании, сохранение → /users, משתמש רגיל без доступа.
// Кейсы: .qa/tests/user-invite/UI-01..UI-05. План: specs/user-invite.md.
// ADMIN2 (компания B). Адреса только qa-auto-inv824-…@example.com. Негативные тесты ничего не создают;
// на случай сбоя проверки в finally всё qa-auto-inv824-… отменяется (с подтверждением).
// USER = «QA Member 2» — только открывает /users/invite, ничего не меняет.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import {
  INVITE_PATH, PENDING, cancelAllInvites, emailField, inviteHeading, invite, nameField, openInvite, rowOf,
  saveButton, submitInvite, usersHeading,
} from '../helpers/invites';

const NAME = 'QA-AUTO Invite 824';
const QA_ROWS = /inv824-/;
const INVALID_EMAIL = 'כתובת האימייל אינה תקינה';
const NAME_REQUIRED = 'יש להזין שם';
const EMAIL_REQUIRED = 'יש להזין אימייל';
const DUPLICATE = 'משתמש עם אימייל זה כבר קיים בחברה';
const run = () => `${Date.now()}-${Math.floor(Math.random() * 1000)}`;

test.describe('הזמנת משתמש חדש — מנהל חשבון (חברה B)', () => {
  test.use({ storageState: authState('admin2') });

  test('אימייל בפורמט שגוי (..com, @., com., נקודות בחלק המקומי) נדחה עם "כתובת האימייל אינה תקינה" #824dde @desktop', async ({ page }) => {
    // UI-01: реджект rej_1794334041066 + комментарий программиста 12.11 (точки в local-part).
    const r = run();
    const invalid = [
      `qa-auto-inv824-${r}@example..com`,
      `qa-auto-inv824-${r}@.example.com`,
      `qa-auto-inv824-${r}@example.com.`,
      `.qa-auto-inv824-${r}@example.com`,
      `qa-auto-inv824-${r}.@example.com`,
      `qa-auto..inv824-${r}@example.com`,
    ];
    try {
      for (const email of invalid) {
        // Каждый адрес — в заново открытой форме, чтобы ошибка не осталась от предыдущего.
        await openInvite(page);
        await submitInvite(page, NAME, email);
        await expect(page.getByText(INVALID_EMAIL, { exact: true }), email).toBeVisible();
        await expect(page).toHaveURL(new RegExp(`${INVITE_PATH}(\\?|$)`));
      }
      // Ни одно приглашение не создано (דרישה 6: «דוחה אימייל בפורמט שגוי»).
      await page.goto('/users');
      await expect(usersHeading(page)).toBeVisible();
      await expect(page.getByRole('row').filter({ hasText: 'פעיל' }).first()).toBeVisible();
      await expect(page.getByRole('row').filter({ hasText: QA_ROWS })).toHaveCount(0);
    } finally {
      await cancelAllInvites(page, QA_ROWS);
    }
  });

  test('שדות חובה ריקים: "יש להזין שם" / "יש להזין אימייל" ליד השדה, ההזמנה לא נשמרת #824dde @desktop', async ({ page }) => {
    // UI-02: דרישות 7–8.
    const email = `qa-auto-inv824-empty-${run()}@example.com`;
    try {
      await openInvite(page);
      // Оба пустые.
      await saveButton(page).click();
      await expect(page.getByText(NAME_REQUIRED, { exact: true })).toBeVisible();
      await expect(page.getByText(EMAIL_REQUIRED, { exact: true })).toBeVisible();
      await expect(page).toHaveURL(new RegExp(`${INVITE_PATH}(\\?|$)`));

      // Только имя → ошибка только у email.
      await openInvite(page);
      await nameField(page).fill(NAME);
      await saveButton(page).click();
      await expect(page.getByText(EMAIL_REQUIRED, { exact: true })).toBeVisible();
      await expect(page.getByText(NAME_REQUIRED, { exact: true })).toHaveCount(0);
      await expect(page).toHaveURL(new RegExp(`${INVITE_PATH}(\\?|$)`));

      // Только email → ошибка только у имени.
      await openInvite(page);
      await emailField(page).fill(email);
      await saveButton(page).click();
      await expect(page.getByText(NAME_REQUIRED, { exact: true })).toBeVisible();
      await expect(page.getByText(EMAIL_REQUIRED, { exact: true })).toHaveCount(0);
      await expect(page).toHaveURL(new RegExp(`${INVITE_PATH}(\\?|$)`));
      await expect(inviteHeading(page)).toBeVisible();
    } finally {
      await cancelAllInvites(page, QA_ROWS);
    }
  });

  test('אימייל של משתמש שכבר בחברה נדחה: "משתמש עם אימייל זה כבר קיים בחברה" #824dde @desktop', async ({ page }) => {
    // UI-03: AC2 (черновик) — email активного участника компании B (самого ADMIN2) берётся из /users.
    await page.goto('/users');
    await expect(usersHeading(page)).toBeVisible();
    const active = page.getByRole('row').filter({ hasText: 'פעיל' }).first();
    await expect(active).toBeVisible();
    const memberEmail = (await active.getByRole('cell').nth(1).innerText()).trim();
    expect(memberEmail).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

    await openInvite(page);
    await submitInvite(page, NAME, memberEmail);
    await expect(page.getByText(DUPLICATE, { exact: true })).toBeVisible();
    await expect(page).toHaveURL(new RegExp(`${INVITE_PATH}(\\?|$)`));

    await page.goto('/users');
    await expect(usersHeading(page)).toBeVisible();
    await expect(rowOf(page, memberEmail)).toHaveCount(1);
  });

  test('שמירה תקינה מחזירה ל-/users עם שורת "הזמנה ממתינה" והרשאת "משתמש רגיל" #824dde @desktop @data', async ({ page }) => {
    // UI-04: דרישות 9–10, AC3. Приглашение отменяется в finally.
    const email = `qa-auto-inv824-ok-${run()}@example.com`;
    try {
      await invite(page, NAME, email);
      const row = rowOf(page, email).first();
      await expect(row).toContainText(NAME);
      await expect(row).toContainText('משתמש רגיל');
      await expect(row).toContainText(PENDING);
    } finally {
      await cancelAllInvites(page, QA_ROWS);
    }
    await expect(page.getByRole('row').filter({ hasText: QA_ROWS })).toHaveCount(0);
  });
});

test.describe('הזמנת משתמש חדש — משתמש רגיל', () => {
  test.use({ storageState: authState('user') });

  test('משתמש רגיל ב-/users/invite רואה "אין לך הרשאה למסך זה", בלי טופס #824dde @desktop @prod-safe', async ({ page }) => {
    // UI-05: AC5. Только просмотр.
    await page.goto(INVITE_PATH);
    await expect(page.getByText('אין לך הרשאה למסך זה', { exact: true })).toBeVisible();
    await expect(page.getByText('המסך זמין למנהלי חשבון בלבד.', { exact: true })).toBeVisible();
    await expect(nameField(page)).toHaveCount(0);
    await expect(saveButton(page)).toHaveCount(0);
  });
});
